"""Partidas opcionales, cancelación trazable, formatos y entregas explícitas a Compras."""
import io,json,re,uuid
import pypdf
import test_inventory as fixture
import test_backup_import as masters

class InventoryDocumentTests(fixture.InventoryTests):
 def received_transfer(self,quantity='10',received='10'):
  self.activate('20');self.activate('0',self.destination)
  doc=self.inv('traspaso',{'accion':'solicitar','origen':self.w,'destino':self.destination,'partidas':[{'sku':self.sku,'cantidad':quantity}],'motivo':'Cancelación recibida','clave':uuid.uuid4().hex})['traspaso']
  doc=self.inv('traspaso',{'accion':'enviar','id':doc['id'],'revision':doc['revision'],'persona':'Entrega','clave':uuid.uuid4().hex})['traspaso']
  return self.inv('traspaso',{'accion':'recibir','id':doc['id'],'revision':doc['revision'],'persona':'Recibe','partidas':[{'sku':self.sku,'cantidad':received}],'clave':uuid.uuid4().hex})['traspaso']
 def cancellation_data(self,doc):
  return {'traspaso':doc['id'],'revision':doc['revision'],'confirmarDevolucion':True,'devolverRecibido':True,'persona':'Recibe origen','entregaDevolucion':'Entrega destino','clave':uuid.uuid4().hex}
 def test_cancel_fully_received_preserves_receipt_and_reverses_both_warehouses_once(self):
  doc=self.received_transfer();data=self.cancellation_data(doc)
  self.assertEqual(self.call('/api/inventarios/traspaso/cancelar',{**data,'confirmarDevolucion':False})[0],400)
  done=self.inv('traspaso/cancelar',data)['traspaso'];self.inv('traspaso/cancelar',data)
  self.assertEqual(done['estado'],'CANCELADA');self.assertEqual(self.amount(),'20');self.assertEqual(self.amount(self.destination),'0');self.assertEqual(done['partidas'][0]['recibido'],'10');self.assertEqual(done['partidas'][0]['devueltoRecibido'],'10');self.assertEqual(done['recepciones'][0]['tipo'],'recibir');self.assertEqual(len(done['recepciones']),2)
  self.assertEqual(self.inv('kardex?almacen='+self.w)['movimientos'][-1]['tipo'],'TRASPASO_CANCELACION_ENTRADA')
  self.assertEqual(self.call('/api/inventarios/traspaso/cancelar',{**data,'revision':done['revision'],'clave':uuid.uuid4().hex})[0],409)
 def test_partial_received_cancel_all_returns_transit_and_received_separately(self):
  doc=self.received_transfer(received='4');done=self.inv('traspaso/cancelar',self.cancellation_data(doc))['traspaso'];self.assertEqual(done['estado'],'CANCELADA');self.assertEqual(self.amount(),'20');self.assertEqual(self.amount(self.destination),'0');self.assertEqual(done['partidas'][0]['devuelto'],'6');self.assertEqual(done['partidas'][0]['devueltoRecibido'],'4')
 def test_received_cancel_negative_requires_explicit_authorization_and_scope(self):
  doc=self.received_transfer();data=self.cancellation_data(doc);warehouse=self.stockuser('almacenista')
  self.assertEqual(self.call('/api/inventarios/traspaso/cancelar',data,warehouse)[0],403)
  self.inv('movimiento',{'almacen':self.destination,'tipo':'SALIDA','sku':self.sku,'cantidad':'8','motivo':'Consumo posterior','clave':uuid.uuid4().hex})
  pending=self.inv('traspaso/cancelar',data)['solicitud'];self.assertEqual(pending['estado'],'PENDIENTE');self.assertEqual(self.amount(),'10');self.assertEqual(self.amount(self.destination),'2')
  decision={'id':pending['id'],'aprobar':True,'comentario':'Validado'};self.assertEqual(self.call('/api/inventarios/operaciones/autorizar',decision)[0],400)
  self.inv('operaciones/autorizar',{**decision,'autorizarNegativo':True});self.assertEqual(self.amount(),'20');self.assertEqual(self.amount(self.destination),'-8')
 def test_received_cancel_rejects_destination_reset_without_partial_writes(self):
  doc=self.received_transfer();review=self.inv('restablecer',{'almacen':self.destination,'revisar':True});self.inv('restablecer',{'almacen':self.destination,'huellaActual':review['huellaActual'],'confirmacion':'RESTABLECER','motivo':'Nuevo ciclo','clave':uuid.uuid4().hex});self.activate('10',self.destination)
  self.assertEqual(self.call('/api/inventarios/traspaso/cancelar',self.cancellation_data(doc))[0],409);self.assertEqual(self.amount(),'10');self.assertEqual(self.amount(self.destination),'10')
 def pdf(self,path,actor=None):
  status,raw,_=self.call('/api/inventarios/'+path,actor=actor);self.assertEqual(status,200,raw[:200]);return ''.join(p.extract_text() for p in pypdf.PdfReader(io.BytesIO(raw)).pages)
 def test_partial_receipt_cancel_only_selected_line_then_remaining(self):
  self.value('/api/requisiciones/maestro',{'archivo':'SEGUNDO.xlsx','contenido':masters.workbook([masters.product('SEGUNDO',B='SEGUNDO',V='0.16')],headers={**masters.HEADERS,'V':'IMPUESTO'})});second=next(m for m in self.po('materiales')['materiales'] if m['sku']=='SEGUNDO');doc=self.confirm(self.order(partidas=[{'materialId':self.material['materialId'],'cantidad':'2','tipoUnidad':'COMPRA','precio':'100','impuesto':'8'},{'materialId':second['materialId'],'cantidad':'3','tipoUnidad':'COMPRA','precio':'50','impuesto':'16'}]));receipt=self.po('recepcion',{'id':doc['id'],'revision':doc['revision'],'clave':uuid.uuid4().hex,'partidas':[{'linea':'1','cantidad':'1'},{'linea':'2','cantidad':'1'}]})['movimiento'];data={'almacen':self.w,'recepcion':receipt['id'],'modo':'PARCIAL','partidas':[{'linea':'1','cantidad':'0.4'}],'devolucionFisica':True,'clave':uuid.uuid4().hex};self.inv('recepciones/cancelar',data);self.inv('recepciones/cancelar',data);self.assertEqual(self.amount(),'6');saved=self.po('documento',extra='&id='+doc['id']);self.assertEqual(saved['partidas'][0]['recibido'],'0.6');self.assertEqual(saved['partidas'][1]['recibido'],'1');self.assertEqual(self.inv('recepciones/devolver?almacen='+self.w+'&recepcion='+receipt['id'])['partidas'][0]['pendienteDevolver'],'0.6');self.inv('recepciones/cancelar',{'almacen':self.w,'recepcion':receipt['id'],'modo':'TOTAL','devolucionFisica':True,'clave':uuid.uuid4().hex});self.assertEqual(self.amount(),'0');self.assertTrue(self.inv('recepciones?almacen='+self.w)['recepciones'][0]['cancelada']);self.assertEqual(self.inv('disponibilidad?almacen='+self.w+'&sku='+self.sku)['comprasRecibidas'],'0')
 def test_cancel_pending_order_quantity_preserves_original_and_receipt_limit(self):
  doc=self.confirm(self.order());doc=self.move(doc,'0.5')['documento'];changed=self.po('accion',{'id':doc['id'],'revision':doc['revision'],'accion':'cancelar_partidas','partidas':[{'linea':'1','cantidad':'1'}]})['documento'];self.assertEqual(changed['partidas'][0]['cantidadOriginal'],'2');self.assertEqual(changed['partidas'][0]['cantidadCancelada'],'1');self.assertEqual(changed['partidas'][0]['cantidad'],'1');self.assertEqual(changed['total'],'108.00');self.assertEqual(self.call('/api/pedidoscompra/accion',{'id':doc['id'],'revision':changed['revision'],'accion':'cancelar_partidas','partidas':[{'linea':'1','cantidad':'0.6'}]})[0],400);self.assertEqual(self.call('/api/pedidoscompra/recepcion',{'id':doc['id'],'revision':changed['revision'],'clave':uuid.uuid4().hex,'partidas':[{'linea':'1','cantidad':'0.6'}]})[0],400);done=self.move(changed,'0.5')['documento'];self.assertEqual(done['estado'],'RECIBIDO');self.assertEqual(self.amount(),'10')
 def test_transfer_cancel_in_transit_returns_only_pending_and_warehouse_needs_approval(self):
  self.activate('20');self.activate('0',self.destination);warehouse=self.stockuser('almacenista');doc=self.inv('traspaso',{'accion':'solicitar','origen':self.w,'destino':self.destination,'partidas':[{'sku':self.sku,'cantidad':'10'}],'motivo':'Traslado','clave':uuid.uuid4().hex},warehouse)['traspaso'];sent=self.inv('traspaso',{'accion':'enviar','id':doc['id'],'revision':doc['revision'],'persona':'Entrega','clave':uuid.uuid4().hex},warehouse)['traspaso'];partial=self.inv('traspaso',{'accion':'recibir','id':doc['id'],'revision':sent['revision'],'persona':'Recibe','partidas':[{'sku':self.sku,'cantidad':'4'}],'clave':uuid.uuid4().hex})['traspaso'];data={'traspaso':doc['id'],'revision':partial['revision'],'persona':'Regresa a origen','clave':uuid.uuid4().hex};self.assertEqual(self.call('/api/inventarios/traspaso/cancelar',data,warehouse)[0],400);pending=self.inv('traspaso/cancelar',{**data,'confirmarDevolucion':True},warehouse)['solicitud'];self.assertEqual(self.amount(),'10');self.assertEqual(self.call('/api/inventarios/operaciones/autorizar',{'id':pending['id'],'aprobar':True,'comentario':'Intento'},warehouse)[0],403);done=self.inv('operaciones/autorizar',{'id':pending['id'],'aprobar':True,'comentario':'Material de regreso verificado'})['traspaso'];self.assertEqual(done['estado'],'CANCELADA_PARCIAL');self.assertEqual(self.amount(),'16');self.assertEqual(self.amount(self.destination),'4');self.assertEqual(done['partidas'][0]['devuelto'],'6');self.assertEqual(self.inv('kardex?almacen='+self.w)['movimientos'][-1]['tipo'],'TRASPASO_CANCELACION');self.assertEqual(self.call('/api/inventarios/traspaso/cancelar',{**data,'revision':done['revision'],'clave':uuid.uuid4().hex,'confirmarDevolucion':True})[0],409)
 def test_handoff_explicit_unique_server_date_pdf_and_scope(self):
  req=self.create_req('2');warehouse=self.stockuser('almacenista');self.assertEqual(self.inv('entregas-compras?almacen='+self.w)['entregas'],[]);data={'almacen':self.w,'id':req['id'],'revision':1,'clave':uuid.uuid4().hex};self.assertEqual(self.call('/api/inventarios/entregar-compras',{**data,'fechaEntrega':'2000-01-01'})[0],400);done=self.inv('entregar-compras',data,warehouse)['entrega'];self.inv('entregar-compras',data,warehouse);self.assertEqual(done['entregadoPor'],'almacenista@inventory.test');self.assertTrue(done['fechaEntrega']);self.assertEqual(self.call('/api/inventarios/entregar-compras',{**data,'clave':uuid.uuid4().hex})[0],409);self.assertEqual(len(self.inv('entregas-compras?almacen='+self.w)['entregas']),1);self.assertEqual(self.inv('entregas-compras?almacen='+self.w+'&desde=2099-01-01')['entregas'],[]);report=self.pdf('reportes/entregas-compras/pdf?almacen='+self.w,warehouse);self.assertIn(req['numero'],report);self.assertIn('Sin pedido',report);self.assertNotIn('Costo',report);self.assertEqual(self.call('/api/inventarios/reportes/entregas-compras/pdf?almacen='+__import__('urllib.parse',fromlist=['quote']).quote(self.destination),actor=warehouse)[0],403);self.assertEqual(self.value('/api/requisiciones/'+req['id']).get('revision',1),1)
 def test_print_transfer_actual_receipt_and_purchase_receipts_cost_visibility(self):
  self.activate('10');self.activate('0',self.destination);doc=self.inv('traspaso',{'accion':'solicitar','origen':self.w,'destino':self.destination,'partidas':[{'sku':self.sku,'cantidad':'3'}],'motivo':'Prueba formatos','clave':uuid.uuid4().hex})['traspaso'];sent=self.inv('traspaso',{'accion':'enviar','id':doc['id'],'revision':doc['revision'],'persona':'Entrega PDF','clave':uuid.uuid4().hex})['traspaso'];self.inv('traspaso',{'accion':'recibir','id':doc['id'],'revision':sent['revision'],'persona':'Recibe PDF','partidas':[{'sku':self.sku,'cantidad':'1'}],'clave':uuid.uuid4().hex});warehouse=self.stockuser('almacenista');out=self.pdf('traspaso/pdf?id='+doc['id']+'&tipo=SALIDA',warehouse);incoming=self.pdf('traspaso/pdf?id='+doc['id']+'&tipo=RECEPCION&indice=0',warehouse);self.assertIn('Salida de traspaso',out);self.assertIn('Recepción real',incoming);self.assertRegex(incoming,r'KILO\s+1\b');self.assertNotIn('Costo unitario',incoming);self.assertIn('Costo unitario',self.pdf('traspaso/pdf?id='+doc['id']+'&tipo=SALIDA'));self.assertEqual(self.call('/api/inventarios/traspaso/pdf?id='+doc['id']+'&tipo=RECEPCION&indice=5')[0],400);po=self.confirm(self.order());self.move(po,'1');text=self.pdf('recepciones/pdf?almacen='+self.w,warehouse);self.assertIn(po['folio'],text);self.assertNotIn('Costo UM',text);self.assertIn('Costo UM',self.pdf('recepciones/pdf?almacen='+self.w))
 def test_negative_inbox_visible_only_allowed_warehouses(self):
  self.activate('0');warehouse=self.stockuser('almacenista');data={'accion':'solicitar','origen':self.w,'destino':self.destination,'partidas':[{'sku':self.sku,'cantidad':'2'}],'motivo':'Pendiente sin stock','clave':uuid.uuid4().hex};doc=self.inv('traspaso',data,warehouse)['traspaso'];items=self.inv('negativos?almacen=TODOS',actor=warehouse);self.assertFalse(items['puedeAutorizar']);self.assertEqual(items['pendientes'][0]['id'],doc['id']);self.assertEqual(items['pendientes'][0]['partidas'][0]['saldoPropuesto'],'-2');self.assertTrue(self.inv('negativos?almacen=TODOS')['puedeAutorizar']);self.assertEqual(self.inv('negativos?almacen='+__import__('urllib.parse',fromlist=['quote']).quote(self.destination))['pendientes'],[])

for name in dir(fixture.InventoryTests):
 if name.startswith('test_') and name not in InventoryDocumentTests.__dict__:setattr(InventoryDocumentTests,name,None)
